-- Read-only diagnostic queries used on rerouteher_test; no schema/data mutation.
BEGIN READ ONLY;
SELECT 'role_count', count(*)::text FROM rerouteher.roles UNION ALL SELECT 'duplicate_title_groups',count(*)::text FROM (SELECT lower(trim(role_title)) FROM rerouteher.roles GROUP BY 1 HAVING count(*)>1) d UNION ALL SELECT 'duplicate_masco_groups',count(*)::text FROM (SELECT masco_code FROM rerouteher.roles GROUP BY 1 HAVING count(*)>1) d UNION ALL SELECT 'shared_esco_groups',count(*)::text FROM (SELECT esco_code FROM rerouteher.roles WHERE esco_code<>'' GROUP BY 1 HAVING count(*)>1) d UNION ALL SELECT 'duplicate_skill_names',count(*)::text FROM (SELECT lower(trim(canonical_name)) FROM rerouteher.skill_taxonomy GROUP BY 1 HAVING count(*)>1) d UNION ALL SELECT 'duplicate_role_skill_pairs',count(*)::text FROM (SELECT role_id,skill_id FROM rerouteher.role_skills GROUP BY 1,2 HAVING count(*)>1) d UNION ALL SELECT 'ambiguous_aliases',count(*)::text FROM (SELECT lower(trim(alias)) FROM rerouteher.skill_aliases GROUP BY 1 HAVING count(DISTINCT skill_id)>1) d;
SELECT 'ROLE',role_title,string_agg(role_id||':'||masco_code,', ' ORDER BY role_id) FROM rerouteher.roles GROUP BY role_title HAVING count(*)>1; SELECT 'SKILL',lower(trim(canonical_name)),string_agg(skill_id,', ' ORDER BY skill_id) FROM rerouteher.skill_taxonomy GROUP BY lower(trim(canonical_name)) HAVING count(*)>1; SELECT role_id,role_title,masco_code,esco_code FROM rerouteher.roles WHERE esco_code='1330.5' OR role_id IN ('R01','R02','R06') ORDER BY role_id; SELECT 'skill_label_different_ids',count(*) FROM (SELECT lower(trim(skill_name)) FROM rerouteher.role_skills GROUP BY 1 HAVING count(DISTINCT skill_id)>1) d;
SELECT 'ROLE_SKILL_NAME',lower(trim(skill_name)),string_agg(DISTINCT skill_id,', ') FROM rerouteher.role_skills GROUP BY 1,2 HAVING count(DISTINCT skill_id)>1; SELECT 'D13_SKILL_LABEL_MISMATCH',count(*) FROM rerouteher.role_skills rs JOIN rerouteher.skill_taxonomy s USING(skill_id) WHERE rs.role_id LIKE 'M%' AND rs.skill_name<>s.canonical_name; SELECT 'VOCATIONAL',count(*),count(*) FILTER(WHERE importance=100),count(*) FILTER(WHERE importance=50) FROM rerouteher.role_skills WHERE role_id='M232102'; SELECT role_id,role_title,masco_code FROM rerouteher.roles WHERE masco_code !~ '^[0-9]{6}$' ORDER BY role_id;
ROLLBACK;

